SELECT id, symbol, interval_code, candle_open_time, decision, original_decision, final_entry_allowed, primary_blocking_stage, confidence_score, total_score, generated_at, created_at FROM crypto_ai.trade_signal WHERE id IN (176655,171559,159285,165415,167616) OR (symbol='EGLDUSDT' AND interval_code='5m' AND candle_open_time IN ('2026-10-11 20:45:00','2026-10-11 20:50:00')) ORDER BY symbol, candle_open_time;
SELECT CASE WHEN f.decision IN ('BUY','STRONG_BUY') AND f.final_entry_allowed=0 THEN 'BULLISH_5M_ENTRY_BLOCKED' WHEN f.decision IN ('NEUTRAL','WATCH') AND f.original_decision IN ('SELL','STRONG_SELL') THEN 'BEARISH_5M_DOWNGRADED' ELSE 'OTHER' END AS ctx_class, COUNT(*) AS buys, SUM(p.realized_pnl < 0) AS losers, ROUND(SUM(p.realized_pnl),6) AS pnl_sum FROM crypto_ai.wallet_trade w JOIN crypto_ai.trade_signal o ON o.id=w.signal_id AND o.interval_code='1m' JOIN crypto_ai.trade_signal f ON f.id=(SELECT f2.id FROM crypto_ai.trade_signal f2 WHERE f2.symbol=o.symbol AND f2.interval_code='5m' AND f2.generated_at<=o.generated_at ORDER BY f2.generated_at DESC LIMIT 1) LEFT JOIN crypto_ai.paper_position p ON p.signal_id=o.id WHERE w.side='BUY' AND w.executed_at BETWEEN '2026-10-10 00:00:00' AND '2026-10-17 10:00:00' GROUP BY ctx_class ORDER BY ctx_class;